def transform(grid):
    from collections import deque

    rows = len(grid)
    cols = len(grid[0])
    if rows == 0 or cols == 0:
        return grid

    visited = set()
    queue = deque()

    # Directions for neighbors
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Add all boundary 8s to the queue and mark them as visited
    for r in range(rows):
        if grid[r][0] == 8:
            queue.append((r, 0))
            visited.add((r, 0))
        if grid[r][cols-1] == 8:
            queue.append((r, cols-1))
            visited.add((r, cols-1))

    for c in range(cols):
        if grid[0][c] == 8:
            queue.append((0, c))
            visited.add((0, c))
        if grid[rows-1][c] == 8:
            queue.append((rows-1, c))
            visited.add((rows-1, c))

    # BFS to mark all 8s connected to the boundary
    while queue:
        r, c = queue.popleft()
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == 8 and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc))

    # Fill all remaining 8s (those not connected to boundary) with 2s
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 8 and (r, c) not in visited:
                grid[r][c] = 2

    return grid
